param([switch]$NoBrowser)
$ErrorActionPreference='Stop'
$stage='C:\Projects\gympro-staging';$project='C:\Projects\gympro-api'
$git='C:\Program Files\Git\cmd\git.exe'
$meta=Get-Content (Join-Path $stage 'installation.json') -Raw|ConvertFrom-Json
$ready=Get-Content (Join-Path $stage 'ready.json') -Raw|ConvertFrom-Json
$cluster=Join-Path $stage 'pgdata';$source=Join-Path $stage 'source';$bin=$meta.postgresBin
$node=(Get-Command node.exe -ErrorAction Stop).Source
$npm=(Get-Command npm.cmd -ErrorAction Stop).Source
$npx=(Get-Command npx.cmd -ErrorAction Stop).Source
$stamp=(Get-Date -Format 'yyyyMMdd-HHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6)
$runRoot=Join-Path $stage ('releases\rehearsal-'+$stamp)
$report=Join-Path $runRoot 'reports';$candidate=Join-Path $runRoot 'candidate\source';$previous=Join-Path $runRoot 'original\source'
$started=$false;$success=$false;$captured=$false;$savedEnv=@{};$originalDirectory=Get-Location
$utf8=New-Object Text.UTF8Encoding($false)
function Run([string]$Exe,[string[]]$Arguments,[string]$Step){
 Write-Host "CHECK: $Step" -ForegroundColor Cyan
 $old=$ErrorActionPreference
 try{$ErrorActionPreference='Continue';& $Exe @Arguments;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 [IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$code)
 if($null -eq $code -or $code -ne 0){throw "Step failed: $Step (exit $code)"}
}
function Reveal([string]$Cipher){$s=ConvertTo-SecureString $Cipher;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p);$s.Dispose()}}
try{
 if($meta.databasePort -ne 55440 -or $meta.apiPort -ne 3200 -or $meta.installedBySid -ne [Security.Principal.WindowsIdentity]::GetCurrent().User.Value -or $ready.passwordProtectedDatabaseVerified -ne $true){throw 'Unexpected staging installation or Windows user.'}
 foreach($port in @(3200,55440)){if(@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue).Count){throw "Stop staging first; port $port is occupied."}}
 if(Test-Path (Join-Path $cluster 'postmaster.pid')){throw 'Staging PID file remains. Inspect shutdown first.'}
 $version=& $node -p 'process.versions.node';if($LASTEXITCODE -ne 0 -or [int]($version.Split('.')[0]) -ne 24){throw 'Node.js 24 is required.'}
 & $git -C $project merge-base --is-ancestor 238b46f HEAD
 if($LASTEXITCODE -ne 0){throw 'Required verified recovery checkpoint is not an ancestor.'}
 $candidateCommit=& $git -C $project rev-parse HEAD
 if($LASTEXITCODE -ne 0){throw 'Cannot identify candidate commit.'};$candidateCommit=$candidateCommit.Trim()
 if($candidateCommit -eq $meta.sourceCommit){throw 'Candidate and installed source commits are identical; no release transition to rehearse.'}
 $inputs=@('src','web','prisma','sql/migrations','sql/baseline-20261016','sql/bootstrap-prerequisites-20261016','package.json','package-lock.json','tsconfig*.json','nest-cli.json')
 & $git -C $project diff --quiet $meta.sourceCommit $candidateCommit -- @inputs
 if($LASTEXITCODE -ne 0){throw 'This first rehearsal requires matching application/dependency/schema inputs. Inspect differences before preparing a feature update.'}
 & $git -C $project diff --quiet HEAD -- @inputs
 if($LASTEXITCODE -ne 0){throw 'Application inputs have local changes. Stop for review.'}
 $files=@(& $git -C $project ls-tree -r --name-only $meta.sourceCommit -- @inputs)
 if($LASTEXITCODE -ne 0 -or $files.Count -lt 10){throw 'Cannot inventory tracked application inputs.'}
 $recovery='C:\Projects\gympro-backups\local-staging-recovery-20261026012229_9c288a\recovery-summary.json'
 $evidence=Get-Content $recovery -Raw|ConvertFrom-Json
 if($evidence.originalStagingContentUnchanged -ne $true -or $evidence.temporaryDatabaseRemoved -ne $true -or $evidence.aclRegressionChecksPassed -ne 7){throw 'Verified staging recovery prerequisite missing.'}
 New-Item -ItemType Directory $report,(Split-Path $candidate),(Split-Path $previous)|Out-Null
 $helper=Join-Path $report 'rehearse.mjs'
 $payloadZip=Join-Path $report 'release-tools.zip'
 [IO.File]::WriteAllBytes($payloadZip,[Convert]::FromBase64String(''))
 Expand-Archive -LiteralPath $payloadZip -DestinationPath $report
 Run $node @('--check',$helper) 'controller-syntax'
 Run $node @('--test',(Join-Path $report 'rehearse-paths.test.mjs')) 'rollback-path-tests'
 Run $git @('-C',$project,'archive','--format=zip',('--output='+(Join-Path $runRoot 'candidate-source.zip')),$candidateCommit) 'archive-candidate'
 Expand-Archive -LiteralPath (Join-Path $runRoot 'candidate-source.zip') -DestinationPath $candidate
 if((Test-Path (Join-Path $candidate 'node_modules')) -or (Test-Path (Join-Path $candidate 'dist'))){throw 'Candidate archive contains dependency/build output.'}
 $envFiles=@(Get-ChildItem $candidate -File -Recurse -Force|Where-Object{$_.Name -match '^\.env($|\.)' -and $_.Name -notmatch '\.(example|sample|template)$'})
 if($envFiles.Count){throw 'Committed environment files detected; inspect privately.'}
 $records=@(foreach($file in $files){
  $old=Join-Path $source $file;$new=Join-Path $candidate $file
  $hash=(Get-FileHash -LiteralPath $old -Algorithm SHA256).Hash.ToLowerInvariant()
  if((Get-FileHash -LiteralPath $new -Algorithm SHA256).Hash.ToLowerInvariant() -ne $hash){throw "Installed/candidate input bytes differ: $file"}
  [ordered]@{file=$file;sha256=$hash}
 })
 [IO.File]::WriteAllText((Join-Path $report 'tracked-inputs.json'),(ConvertTo-Json -InputObject $records -Depth 5)+"`n",$utf8)
 [IO.File]::WriteAllText((Join-Path $report 'release-plan.json'),([ordered]@{originalSourceCommit=$meta.sourceCommit;candidateCommit=$candidateCommit;applicationInputsIdentical=$true;source=$source;candidate=$candidate;previous=$previous;apiPort=3200;databasePort=55440;databaseMigrationsPermitted=$false}|ConvertTo-Json)+"`n",$utf8)
 foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$|NPM_CONFIG_IGNORE_SCRIPTS$|NPM_CONFIG_PRODUCTION$|NPM_CONFIG_OMIT$)'){$savedEnv[$item.Name]=$item.Value;[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}}
 $captured=$true
 $env:DATABASE_URL='postgresql://gympro_app@127.0.0.1:1/gympro_saas';$env:AUTH_DATABASE_URL='postgresql://gympro_auth@127.0.0.1:1/gympro_saas';$env:SESSION_DATABASE_URL='postgresql://gympro_session@127.0.0.1:1/gympro_saas'
 Set-Location $candidate
 Run $npm @('ci','--no-audit','--no-fund') 'candidate-npm-ci'
 Run $npx @('--no-install','prisma','generate') 'candidate-prisma-generate'
 Run $npm @('run','build') 'candidate-build'
 foreach($record in $records){if((Get-FileHash -LiteralPath (Join-Path $candidate $record.file) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $record.sha256){throw "Build modified tracked input: $($record.file)"}}
 Set-Location $stage
 $credentials=Get-Content (Join-Path $stage 'credentials.dpapi.json') -Raw|ConvertFrom-Json
 $env:GYMPRO_RELEASE_ADMIN=Reveal $credentials.admin;$env:GYMPRO_RELEASE_APP=Reveal $credentials.app;$env:GYMPRO_RELEASE_AUTH=Reveal $credentials.auth;$env:GYMPRO_RELEASE_SESSION=Reveal $credentials.session
 if($NoBrowser){$env:GYMPRO_RELEASE_NO_BROWSER='1'}
 $started=$true
 Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-l',(Join-Path $report 'server.log'),'-o','-h 127.0.0.1 -p 55440','-w','start') 'start-owned-cluster'
 Run $node @($helper,$stage,$report,$candidate,$previous,$candidateCommit) 'controlled-switch-and-rollback'
 $result=Get-Content (Join-Path $report 'release-summary.json') -Raw|ConvertFrom-Json
 foreach($check in @('candidateReady','originalReady','rollbackDone','originalSourceRestored','automaticChecksPassed','stagingApiStopped')){if($result.$check -ne $true){throw "Release evidence incomplete: $check"}}
 if($result.automaticCheckCount -ne 8 -or $result.databaseMigrationsApplied -ne $false -or $result.workingDatabaseUsed -ne $false){throw 'Unexpected release scope/check count.'}
 $success=$true
}catch{Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red;Write-Host "Retain all release paths and private reports: $runRoot";Write-Host 'Do not reinstall, delete release directories, or rerun blindly.'}finally{
 try{if($started -and (Test-Path (Join-Path $cluster 'postmaster.pid'))){Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-m','fast','-w','stop') 'stop-owned-cluster'}}catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}finally{
  if($captured){foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$|NPM_CONFIG_IGNORE_SCRIPTS$|NPM_CONFIG_PRODUCTION$|NPM_CONFIG_OMIT$)'){[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}};foreach($key in $savedEnv.Keys){[Environment]::SetEnvironmentVariable($key,$savedEnv[$key],'Process')}}
  Set-Location $originalDirectory
 }
 $apiPortFree=(@(Get-NetTCPConnection -LocalPort 3200 -State Listen -ErrorAction SilentlyContinue).Count -eq 0)
 if(-not $apiPortFree){$success=$false;Write-Host 'FAIL: Staging API port remains occupied; inspect shutdown.'}
 if(Test-Path $report){[ordered]@{completed=$success;clusterStopped=(-not(Test-Path (Join-Path $cluster 'postmaster.pid')));stagingApiPortFree=$apiPortFree;reportFolder=$report}|ConvertTo-Json|Set-Content (Join-Path $report 'run-status.json') -Encoding UTF8}
}
if(-not $success){exit 1}
Write-Host 'PASS: Separate candidate build, controlled source switch and rollback startup verified.' -ForegroundColor Green
Write-Host 'PASS: Original application source restored; business schema/data/sequences unchanged; allowed owner sessions scoped and revoked.'
Write-Host 'PASS: Staging API and database stopped; original and candidate release files retained.'
Write-Host "Reports: $report"
Write-Host 'PENDING: User browser acceptance for candidate and rolled-back original, then Git/dashboard checkpoint.'
Write-Host 'Application inputs matched: this rehearses release handling, not a new business feature.'
Write-Host 'No database migration, permission change, development database use, Git commit or KBZPay operation.'
